mapper.select:
select
    coalesce(sum(case
        when status = #{successStatus}
            and payed_time >= #{todayStart}
            and payed_time < #{tomorrowStart}
        then amount else 0 end), 0) as todayPaidAmount,
    coalesce(sum(case
        when status = #{successStatus}
            and payed_time >= #{todayStart}
            and payed_time < #{tomorrowStart}
        then 1 else 0 end), 0) as todayPaidOrderCount,
    coalesce(sum(case
        when status = #{notPayStatus}
            and created_time >= #{todayStart}
            and created_time < #{tomorrowStart}
        then 1 else 0 end), 0) as todayUnpaidOrderCount
from pay_order

select
    hour(payed_time) as hour,
    coalesce(sum(amount), 0) as amount
from pay_order
where status = #{successStatus}
  and payed_time >= #{todayStart}
  and payed_time < #{tomorrowStart}
group by hour(payed_time)
order by hour asc

select
    pay_id as payId,
    hour(payed_time) as hour,
    coalesce(sum(amount), 0) as amount
from pay_order
where status = #{successStatus}
  and payed_time >= #{todayStart}
  and payed_time < #{tomorrowStart}
group by pay_id, hour(payed_time)
order by pay_id asc, hour asc
